const LIBRARY = {};
for (const [level, words] of Object.entries(RAW_LIBRARY)) {
  LIBRARY[level] = words.map(w => ({ word: w.w, turkish: w.t, example: w.e, level }));
}

const LEVELS = ["A1", "A2", "B1", "B2"];

function shuffle(arr) { return [...arr].sort(() => Math.random() - 0.5); }

function generateQuiz(word, turkish, allWords) {
  const distractors = allWords
    .filter(w => w.word !== word && w.turkish !== turkish)
    .sort(() => Math.random() - 0.5)
    .slice(0, 3)
    .map(w => w.turkish);
  const options = [...distractors, turkish].sort(() => Math.random() - 0.5);
  const correctIdx = options.indexOf(turkish);
  return { word, options, correctIdx };
}

// ============================================================
// BASIT HASH (şifre için — gerçek uygulamada bcrypt kullanın)
// ============================================================
async function hashPassword(password) {
  const encoder = new TextEncoder();
  const data = encoder.encode(password + "linguaai_salt_2025");
  const hashBuffer = await crypto.subtle.digest("SHA-256", data);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, "0")).join("");
}

